## Prime Number Checker Function in JavaScript

Here's a function in JavaScript that checks if any of the numbers in the input array is a valid prime number.

```javascript
function isPrime(num) {
  if (num <= 1) return false;
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) return false;
  }
  return true;
}

function checkPrimeNumbers(numbers) {
  if (!Array.isArray(numbers) || numbers.length!== 5) {
    throw new Error("Input must be an array of 5 numbers");
  }
  numbers.forEach((num) => {
    if (typeof num!== "number" || num % 1!== 0) {
      throw new Error("All elements in the array must be integers");
    }
    if (isPrime(num)) {
      console.log(`The prime number is: ${num}`);
    }
  });
}

// Example usage:
checkPrimeNumbers([2, 3, 4, 5, 6]);
```

